/**
 * The contour-line wave field from the Ahadubit company profile — the site's
 * one signature element, used in the homepage hero. Static, cacheable SVG
 * (generated by scripts/generate-waves.mjs) so it stays out of the HTML.
 */
export default function Waves({ className = "" }: { className?: string }) {
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src="/waves/hero.svg"
      alt=""
      aria-hidden="true"
      width={1200}
      height={700}
      decoding="async"
      fetchPriority="high"
      className={`waves ${className}`}
    />
  );
}
